    recompute_and_format(frm);

    // Recompute when user edits grid cells
    const grid = frm.fields_dict.plantation_type_table && frm.fields_dict.plantation_type_table.grid;
    if (grid && grid.wrapper) {
      $(grid.wrapper)
        .off('.plant_sum')
        .on('keyup.plant_sum change.plant_sum',
          '[data-fieldname="no_of_plants"], [data-fieldname="acre"]',
          () => recompute_and_format(frm));
    }

    // Catch add/remove row
    frappe.ui.form.on('Annual Plantation Update', {
      plantation_type_table_add:    f => recompute_and_format(f),
      plantation_type_table_remove: f => recompute_and_format(f),
    });
  },

  // If user edits totals manually, just normalize to Burmese digits
  total_plant(frm) { format_totals_only(frm); },
  total_area(frm)   { format_totals_only(frm); },

  validate(frm) {
    // Final normalization on save
    recompute_and_format(frm);
    format_totals_only(frm);
  }
});

/* ================= Core flow ================= */

function recompute_and_format(frm) {
  if (frm.__plant_sum_guard) return;
  frm.__plant_sum_guard = true;

  try {
    const rows = frm.doc.plantation_type_table || [];

    let allPlantsFilled = true;
    let allAcreFilled   = true;

    let totalPlants = 0;
    let totalAcre   = 0;

    rows.forEach(r => {
      // Normalize row values (accept Burmese/Arabic)
      const plantsNum = parse_mm_number(r.no_of_plants);
      const acreNum   = parse_mm_number(r.acre);

      // Detect completeness
      const hadPlants = has_any_digit(r.no_of_plants);
      const hadAcre   = has_any_digit(r.acre);
      if (!hadPlants) allPlantsFilled = false;
      if (!hadAcre)   allAcreFilled   = false;

      // Sum only numeric contributions
      if (isFinite(plantsNum)) totalPlants += plantsNum;
      if (isFinite(acreNum))   totalAcre   += acreNum;

      // Write back the row display in Burmese numerals
      const plantsDisplay = hadPlants && isFinite(plantsNum)
        ? to_mm_digits(String(Math.round(plantsNum)))
        : (hadPlants ? to_mm_digits(clean_numeric_string(r.no_of_plants)) : '');

      const acreDisplay = hadAcre && isFinite(acreNum)
        ? to_mm_digits(trim_trailing_zeros(acreNum.toFixed(2)))
        : (hadAcre ? to_mm_digits(clean_numeric_string(r.acre)) : '');

      safe_set_child_value(frm, r, 'no_of_plants', plantsDisplay);
      safe_set_child_value(frm, r, 'acre',         acreDisplay);
    });

    // Auto-fill totals only if column is fully filled in all rows
    if (rows.length && allPlantsFilled) {
      frm.set_value('total_plant', to_mm_digits(String(Math.round(totalPlants))));
    }
    if (rows.length && allAcreFilled) {
      frm.set_value('total_area', to_mm_digits(trim_trailing_zeros(totalAcre.toFixed(2))));
    }

    // If NOT fully filled, do NOT overwrite totals—user can input manually.
    // (We still format totals if they already exist and user typed them.)
    format_totals_only(frm);

  } finally {
    frm.__plant_sum_guard = false;
  }
}

/* ============ Total fields formatting only ============ */

function format_totals_only(frm) {
  // If user typed totals manually (Burmese or Arabic), just normalize to Burmese
  const tp_raw = String(frm.doc.total_plant || '');
  const ta_raw = String(frm.doc.total_area   || '');

  if (tp_raw) {
    const n = parse_mm_number(tp_raw);
    const formatted = isFinite(n) ? to_mm_digits(String(Math.round(n))) : to_mm_digits(clean_numeric_string(tp_raw));
    if (formatted !== frm.doc.total_plant) frm.set_value('total_plant', formatted);
  }

  if (ta_raw) {
    const n = parse_mm_number(ta_raw);
    const formatted = isFinite(n) ? to_mm_digits(trim_trailing_zeros(n.toFixed(2))) : to_mm_digits(clean_numeric_string(ta_raw));
    if (formatted !== frm.doc.total_area) frm.set_value('total_area', formatted);
  }
}

/* ============ Helpers ============ */

// Safe child set (works even before dt is present on the row)
function safe_set_child_value(frm, row, fieldname, value) {
  const dt = row.doctype || row.dt || guess_child_dt(frm, 'plantation_type_table');
  if (row.name && dt) {
    frappe.model.set_value(dt, row.name, fieldname, value);
  }
}

function guess_child_dt(frm, table_fieldname) {
  const df = frm.fields_dict[table_fieldname] && frm.fields_dict[table_fieldname].df;
  return df && df.options ? df.options : undefined; // options holds child DocType name
}

// Has any digit (Burmese or Arabic)
function has_any_digit(v) {
  if (!v && v !== 0) return false;
  const s = String(v);
  return /[0-9၀၁၂၃၄၅၆၇၈၉]/.test(s);
}

// Clean numeric-ish string: strip spaces/commas; keep dot and minus
function clean_numeric_string(v) {
  if (v == null) return '';
  let s = mm_to_ascii_digits(String(v));
  s = s.replace(/[,\s]/g, '');
  return s;
}

// Parse Burmese or Arabic numeric to Number; NaN if not parseable
function parse_mm_number(v) {
  if (v == null || v === '') return NaN;
  const s = clean_numeric_string(v);
  const n = parseFloat(s);
  return isNaN(n) ? NaN : n;
}

// Trim trailing zeros and dot ("12.50"->"12.5", "10.00"->"10")
function trim_trailing_zeros(s) {
  if (!s) return s;
  if (!s.includes('.')) return s;
  return s.replace(/\.?0+$/, '');
}

/* ============ Burmese digit conversion ============ */

// ASCII → Myanmar digits
function to_mm_digits(s) {
  if (s == null) return '';
  const map = {
    '0':'၀','1':'၁','2':'၂','3':'၃','4':'၄',
    '5':'၅','6':'၆','7':'၇','8':'၈','9':'၉','-':'-','+':'+','.':'.'
  };
  return String(s).split('').map(ch => map[ch] ?? ch).join('');
}

// Myanmar → ASCII digits (for parsing)
function mm_to_ascii_digits(s) {
  if (s == null) return '';
  const map = {
    '၀':'0','၁':'1','၂':'2','၃':'3','၄':'4',
    '၅':'5','၆':'6','၇':'7','၈':'8','၉':'9',
    '၊':',','။':'.'
  };
  return String(s).split('').map(ch => map[ch] ?? ch).join('');
}
